/* the Endless floor deck: crosswalk cards for the steps ∞1 to ∞86 (work/phaseJ/decks for ∞1-∞26, work/crosswalk/decks3 for ∞27-∞78, work/phaseK/decks for ∞79-∞86) */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Ψ"]=[{"q": "A map from A × A to B names every function from A to B. What must every function from B to B have?", "a": "a fixed point, some b with f(b) = b", "w": ["an undo", "exactly two fixed points", "no fixed point at all"], "why": "The fixed-point technique."}, {"q": "B = {true, false} and f is “not”. What does the fixed-point technique then say about A?", "a": "no map names every function from A to B", "w": ["A must be empty", "A must be finite", "every map names them all"], "why": "“Not” keeps nothing fixed, so the namer cannot exist."}, {"q": "Which result is the fixed-point technique read with B the true-or-false set and A a set?", "a": "the parts of a set outrun its members", "w": ["every set has a largest member", "two sets of one size match", "every part has a complement"], "why": "Rung 35 as one case."}, {"q": "The set of all things that are not members of themselves. What does the diagonal show?", "a": "no set holds exactly those things", "w": ["it holds itself", "it is empty", "it is the set of all sets"], "why": "Rung 2, read down the diagonal."}, {"q": "What does each diagonal argument do on the diagonal?", "a": "reads each thing at itself and takes the opposite", "w": ["counts the members twice", "adds one to every row", "sorts the rows"], "why": "One argument, five times."}, {"q": "In arithmetic the fixed-point idea gives a positive result. What is it?", "a": "a statement that speaks about itself", "w": ["a proof of every true statement", "a largest number", "a machine that decides stopping"], "why": "Rung 38’s self-reading statement."}, {"q": "If a machine decided stopping, which map would the fixed-point technique then refute?", "a": "“stop if the input loops, loop if it stops”, which keeps nothing fixed", "w": ["“add one to the output”, which keeps some value fixed", "the machine that always stops on every input", "the do-nothing machine, which keeps everything fixed"], "why": "Rung 41, read as one case."}, {"q": "The fixed-point technique. Its accepted name?", "a": "Lawvere’s fixed-point theorem", "w": ["Brouwer’s fixed-point theorem", "the Banach contraction principle", "Tarski’s fixed-point theorem"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞ל‎"]=[{"q": "f maps X to Y and V is a part of Y. What is f⁻¹(V)?", "a": "the members of X whose outputs land in V", "w": ["the outputs of V", "the members of Y not in V", "the members of X that miss V"], "why": "Pulling back."}, {"q": "Which of these does pulling back keep?", "a": "unions, meets and the part left over", "w": ["only unions", "only meets", "none of them"], "why": "The pull-back-keeps technique."}, {"q": "f[P] ⊆ V exactly when P ⊆ f⁻¹(V). Which side of pulling back is taking images?", "a": "the left side", "w": ["the right side", "neither side", "both sides at once"], "why": "The image-left technique."}, {"q": "An output y is in f∀[P] when…", "a": "every member sent to y is in P", "w": ["some member sent to y is in P", "no member is sent to y", "y is in P"], "why": "The every-image, right of pulling back."}, {"q": "How many right sides can one map between orders have?", "a": "at most one", "w": ["exactly two", "any number", "always one"], "why": "The one-right-side technique."}, {"q": "Which quantifier sits on the left of pulling back?", "a": "some", "w": ["every", "not", "if"], "why": "Images are the some-guess from below."}, {"q": "With ◇P = s[t⁻¹(P)], how is □P written from ◇?", "a": "W ∖ ◇(W ∖ P)", "w": ["◇P ∪ P", "◇(◇P)", "W ∖ P"], "why": "The reach-modal technique: necessary and possible are the same pair."}, {"q": "Pulling back along f, written f*. Its accepted name for the set f⁻¹(V)?", "a": "the preimage or inverse image", "w": ["the direct image", "the dual image", "the fibre product"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞1"]=[{"q": "Functions from A × S to B × S match functions from A to what?", "a": "functions from S to B × S", "w": ["functions from B to S", "pairs A × B", "lists of B"], "why": "The state-wrap technique."}, {"q": "Under the maybe wrapper, g ⋆ f fails at a when…", "a": "f fails at a, or f gives b and g fails at b", "w": ["only when f and g both fail", "only when g fails at a", "never: maybe cannot fail"], "why": "The maybe-row technique."}, {"q": "What two maps must a wrapper have for wrapped programs to run in a row?", "a": "one to wrap a plain value, one to unwrap a wrapper of wrappers", "w": ["one to add two values, one to multiply them", "one to copy a value, one to delete it", "one to read a name, one to write a name"], "why": "Wrap and join."}, {"q": "A lawful wrapper’s wrapped programs, with wrap as do-nothing and ⋆ as the row. What do they form?", "a": "a category", "w": ["a ring", "a single set", "a total order"], "why": "The wrapped-category technique."}, {"q": "Which wrapper comes from freeing after forgetting for joining?", "a": "the list wrapper", "w": ["the maybe wrapper", "the state wrapper", "the chance wrapper"], "why": "The free-wrapper technique."}, {"q": "Chance rules f : A → T(B) and g : B → T(C). What does g ⋆ f give c, from a?", "a": "Σ over b of f(a)(b) · g(b)(c)", "w": ["f(a)(c) + g(a)(c)", "the largest f(a)(b)", "f(a)(b) for a single b"], "why": "The chance-row technique: a product of chance grids."}, {"q": "Where does every left-and-right pair F ⊣ U give a wrapper?", "a": "U ∘ F", "w": ["F ∘ F", "U ∘ U", "F alone"], "why": "Freeing after forgetting."}, {"q": "A lawful wrapper. Its accepted name?", "a": "a monad", "w": ["a monoid", "a functor category", "a lens"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Υ"]=[{"q": "What does the chain rule say about the slope of a chain?", "a": "it is the product of the slopes along it", "w": ["it is the sum of the slopes", "it is the largest slope", "it is the first slope"], "why": "Slope-taking keeps the row."}, {"q": "Taking slope grids sends running in a row to what?", "a": "running in a row of grids, a product", "w": ["a sum of grids", "the do-nothing grid", "a single number"], "why": "The slope-map technique: a map of categories."}, {"q": "A lens has two parts. What are they?", "a": "a get forward and a put that comes back with a correction", "w": ["two gets, both going forward", "a get forward and a copy of it", "a read of the data and a delete"], "why": "From keeping two copies of data in step."}, {"q": "Two lenses in a row. What do they make?", "a": "a lens, without care for brackets", "w": ["a pair that cannot run", "a single get", "a wrapper"], "why": "The lens-chain technique."}, {"q": "A learner b = w x with error ½(b − t)². What is the knob’s slope?", "a": "(b − t) x", "w": ["(b − t) w", "b − t", "w x"], "why": "The one-step-learner technique."}, {"q": "A small enough step against a knob’s slope does what to the error?", "a": "lowers it, unless the slope is 0", "w": ["raises it", "leaves it alone", "doubles it"], "why": "Going downhill."}, {"q": "In two learners in a row, which put runs first?", "a": "the second learner’s, then the first’s", "w": ["the first learner’s", "both at once", "neither: they share one put"], "why": "The learner-chain technique: the error is carried backwards."}, {"q": "The backward pass through the layers. Its accepted name?", "a": "backpropagation, reverse-mode automatic differentiation", "w": ["forward-mode differentiation", "gradient clipping", "the Para construction"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Φ"]=[{"q": "A database on a schema S, read as rung 47 did. What is it?", "a": "a map from the schema to sets", "w": ["a single table", "a list of numbers", "a function from sets to S"], "why": "Data as a map from the schema."}, {"q": "F : S → T and data J on T. What is the data moved back to S?", "a": "J ∘ F, reading through the map", "w": ["F ∘ J", "J alone", "the empty data"], "why": "The pull-data technique."}, {"q": "F sends tables A and B to one table C. What does the left move Σ put in C?", "a": "the rows of both tables side by side", "w": ["the pairs of rows", "only the rows of A", "no rows"], "why": "Gluing, left of the backward move."}, {"q": "And what does the right move Π put in C?", "a": "the pairs of rows, I(A) × I(B)", "w": ["the rows side by side", "only the rows of B", "the shared rows only"], "why": "Joining, right of the backward move."}, {"q": "Moving workers forward into a schema with teams, what does Σ do?", "a": "gives each worker a team of their own", "w": ["puts every worker on one team", "drops every worker", "asks for teams first"], "why": "The new-table technique."}, {"q": "And what does Π do there?", "a": "puts every worker on one team", "w": ["gives each worker a team of their own", "makes no teams", "doubles the workers"], "why": "The new-table technique."}, {"q": "The answers to a query with only ands and somes in data I match what?", "a": "the maps of data from the query’s pattern into I", "w": ["the rows of I", "the tables of the schema", "the maps from I into the pattern"], "why": "The query-is-map technique."}, {"q": "The forward move Σ along a map of schemas. Its accepted name?", "a": "the left Kan extension", "w": ["the right Kan extension", "the pullback", "the coproduct"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞r"]=[{"q": "On signs, what is + plus −?", "a": "⊤, sign unknown", "w": ["+", "−", "0"], "why": "Adding signs is not exact."}, {"q": "On signs, what is − times −?", "a": "+", "w": ["−", "0", "⊤"], "why": "Multiplying signs is exact."}, {"q": "The blurred run of x · x + 1 gives + for every input sign. What follows?", "a": "x · x + 1 is positive for every number x", "w": ["only for positive x", "nothing about real numbers", "it is 0 somewhere"], "why": "The sign-run technique."}, {"q": "Blur α and sharpen γ: α(A) ≤ s exactly when A ⊆ γ(s). Which is left?", "a": "blur is left of sharpen", "w": ["sharpen is left of blur", "neither", "both are right"], "why": "The blur-pair technique."}, {"q": "What does the blur-sound technique promise of the blurred run?", "a": "whatever it says covers every real run", "w": ["it is exact", "it finds every bug with no alarm", "it runs faster than the program"], "why": "f(A) ⊆ γ(f♯(α(A)))."}, {"q": "An interval end keeps moving in a loop. What does widening do to it?", "a": "sends it to ±∞, so the analysis stops", "w": ["stops the program", "rounds it to 0", "drops the loop"], "why": "The widen technique."}, {"q": "A machine check never calls an unsafe program safe. What must it then do, by rung 41?", "a": "call some safe program unsafe", "w": ["decide every program exactly", "never finish", "call every program unsafe"], "why": "The false-alarm technique."}, {"q": "Checking by running a blurred copy. Its accepted name?", "a": "abstract interpretation", "w": ["model checking", "symbolic execution", "fuzz testing"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Τ"]=[{"q": "Rung 41’s reading machines and rung 40’s programs with state share which shape?", "a": "a set of states with one map out, giving an output and a next state", "w": ["a list of numbers", "a tree of choices", "a single function into the states"], "why": "A machine is a map out of a set."}, {"q": "A map of stream machines sends each state to a state with what?", "a": "the same row of outputs", "w": ["a larger output", "no output", "the reverse row"], "why": "The map-keeps-outputs technique."}, {"q": "Two states tied by a relation that survives every step. What can no experiment do?", "a": "tell them apart", "w": ["run them", "count their outputs", "start them"], "why": "The bisimulation technique."}, {"q": "How many maps does every stream machine have into the streams?", "a": "exactly one", "w": ["none", "two", "one for each state"], "why": "The last-machine technique."}, {"q": "How are two streams proved equal in this step?", "a": "by showing a relation that survives every step", "w": ["by induction on length", "by checking the first output", "by counting outputs"], "why": "The relation-proof technique."}, {"q": "The image of a reading machine in the last machine. What is it?", "a": "the smallest machine for its pattern, among those with every state reachable", "w": ["the largest machine that reads the same pattern", "the empty machine, with no states", "a machine with exactly one state"], "why": "The least-machine technique."}, {"q": "If Z is a last machine for the shape F, what is its map c : Z → F(Z)?", "a": "undoable", "w": ["constant", "empty", "never one to one"], "why": "The last-is-matched technique; for “a set of nexts” it would need sets that hold themselves."}, {"q": "Proving equality with a relation that survives every step. Its accepted name?", "a": "coinduction", "w": ["induction", "recursion", "bisection"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞x"]=[{"q": "Which two free moves are taken away in this logic?", "a": "copying a given and throwing one away", "w": ["adding an option and dropping a not", "swapping and grouping", "writing x + 0 for x"], "why": "Each given is spent once."}, {"q": "In a proof with only ⊗ and ⊸, no copying and no throwing away, what is every letter’s signed count?", "a": "0", "w": ["1", "2", "the number of lines"], "why": "The balance technique."}, {"q": "Which follows from A & B?", "a": "A, and also B", "w": ["A ⊗ B", "nothing", "A ⊸ B"], "why": "The two-ands technique: & is your choice of one."}, {"q": "Does A ⊗ B give A alone?", "a": "no: B would be thrown away", "w": ["yes, always", "only when A is B", "only with a !"], "why": "Both at once must both be spent."}, {"q": "From coin ⊗ coin and coin ⊸ coffee, what can be proved?", "a": "coffee ⊗ coin", "w": ["coffee ⊗ coffee", "coin alone", "coffee alone"], "why": "The spend-to-get technique."}, {"q": "Which givens may be copied or dropped?", "a": "only those marked !", "w": ["all givens", "none ever", "only those joined by &"], "why": "The bang-copy technique."}, {"q": "For a space V other than {0}, what is v ↦ v ⊗ v?", "a": "not straight", "w": ["straight", "undoable", "constant"], "why": "The no-straight-copy technique: a quantum state cannot be copied."}, {"q": "The logic in which each given is spent once. Its accepted name?", "a": "linear logic", "w": ["intuitionistic logic", "modal logic", "relevance-free logic"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Η"]=[{"q": "What must a distance obey to be read as a category?", "a": "the detour rule and d(x, x) = 0", "w": ["symmetry only", "d(x, y) = 1 for all pairs", "the parallel rule"], "why": "The detour-is-composing technique."}, {"q": "In such a category, what is running in a row?", "a": "adding the numbers", "w": ["multiplying the numbers", "taking the larger", "taking the smaller"], "why": "Arrows are numbers."}, {"q": "A map that does not stretch. What do two in a row make?", "a": "a map that does not stretch", "w": ["a stretch by 2", "an undo", "a constant map"], "why": "The short-row technique."}, {"q": "The largest gap between d(−, x) and d(−, y) is exactly what?", "a": "d(x, y)", "w": ["0", "2 d(x, y)", "1"], "why": "The distances-to technique: a point is its distances."}, {"q": "Two points at distance d. What is the magnitude?", "a": "2/(1 + e⁻ᵈ)", "w": ["2", "1 + d", "2d"], "why": "The two-point technique."}, {"q": "Two points far apart. What does the magnitude come near?", "a": "2", "w": ["1", "0", "∞"], "why": "Far points count as two."}, {"q": "A two-point space scaled by t, as t → 0. What does the magnitude go to?", "a": "1", "w": ["2", "0", "∞"], "why": "The scale-count technique: close points count as one."}, {"q": "The number that counts how many points a space effectively has. Its accepted name?", "a": "magnitude", "w": ["Hausdorff measure", "cardinality", "diameter"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞v"]=[{"q": "A kind of structure gives, for each finite set of labels, what?", "a": "the set of structures on it, carrying relabellings along", "w": ["one number, the count of structures", "a single tree on those labels", "a list of sizes, one per label"], "why": "A map of categories."}, {"q": "The number of structures on U depends on what alone?", "a": "the size of U", "w": ["the names of the labels", "the order of the labels", "the largest label"], "why": "The size-only technique."}, {"q": "What is the shadow of F · G?", "a": "F(x) G(x)", "w": ["F(x) + G(x)", "F(G(x))", "F(x)/G(x)"], "why": "The product-shadow technique."}, {"q": "Every shuffle of U is one set of what?", "a": "cycles", "w": ["trees", "pairs", "orders"], "why": "The shuffles-are-cycles technique: S = E ∘ C."}, {"q": "Orders and shuffles both have n! on n labels. Are they the same kind for n ≥ 2?", "a": "no: no matching commutes with every relabelling", "w": ["yes, always: equal counts mean one kind", "only for n = 3", "only when n is even"], "why": "The not-the-same-kind technique."}, {"q": "How many functions are there from {1, …, n} to itself?", "a": "nⁿ", "w": ["n!", "2ⁿ", "n²"], "why": "As many as the doubly rooted trees."}, {"q": "So how many trees are there on n labels?", "a": "nⁿ⁻²", "w": ["nⁿ", "n!", "2ⁿ⁻¹"], "why": "The two-ways technique."}, {"q": "A kind of structure on labels. Its accepted name?", "a": "a combinatorial species", "w": ["a partition", "a generating set", "a graph family"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Ε"]=[{"q": "In how many ways can five things be bracketed?", "a": "14", "w": ["5", "10", "42"], "why": "Counting bracketings."}, {"q": "How is B(n) found from smaller counts?", "a": "the sum of B(k) B(n − k) over the last split k", "w": ["B(n − 1) + B(n − 2), as for rabbits", "n · B(n − 1), one per place", "2 B(n − 1), bracket left or right"], "why": "The last-split technique."}, {"q": "How many single regroupings does each bracketing of n things allow?", "a": "n − 2", "w": ["n", "n − 1", "2"], "why": "The single-move technique."}, {"q": "The bracketings of four things, joined by single regroupings. What shape do they make?", "a": "a pentagon", "w": ["a square", "a triangle", "a cube"], "why": "Five corners, five edges."}, {"q": "For sets, the regrouping (A × B) × C → A × (B × C) is a matching. What else is it?", "a": "natural: it commutes with functions run on each part", "w": ["the do-nothing map on A × B × C", "a swap of A and C", "not a function at all"], "why": "The regroup-matching technique."}, {"q": "When regroupings are only matchings, what must agree for brackets not to matter?", "a": "the two routes round the pentagon", "w": ["every pair of sets", "the sizes of A, B, C", "the two sides of a triangle only"], "why": "The pentagon-route technique."}, {"q": "If the pentagon rule holds, what happens round every face of the solid for five things?", "a": "it closes: going round does nothing", "w": ["it fails on one face", "it doubles the matching", "the faces cannot be drawn"], "why": "The faces-fill technique."}, {"q": "The counts 1, 1, 2, 5, 14, 42. Their accepted name?", "a": "the Catalan numbers", "w": ["the Bell numbers", "the Fibonacci numbers", "the Stirling numbers"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞א‎"]=[{"q": "In a quantum circuit drawing, what does side by side mean?", "a": "the tensor product", "w": ["adding the states", "running in a row", "reading the qubit"], "why": "Boxes, wires, side by side."}, {"q": "A box on one wire and a box on another. What can they do?", "a": "slide past each other, the result unchanged", "w": ["never pass each other", "cancel each other out", "swap their wires"], "why": "The wire-slide technique."}, {"q": "A loop of wire, cap after cup. What number is it?", "a": "n, the dimension", "w": ["0", "1", "2n"], "why": "The cup-cap technique."}, {"q": "A wire bent round a cup and back round a cap. What does it equal?", "a": "a straight wire, the do-nothing", "w": ["a loop", "a cap", "zero"], "why": "The yanking technique."}, {"q": "A box A slides round a cup to the other wire. What does it become?", "a": "its transpose, Aᵀ", "w": ["A unchanged", "A⁻¹", "the do-nothing"], "why": "The slide-round-cup technique."}, {"q": "In teleportation, with what chance does each of the sender’s four readings come?", "a": "¼", "w": ["½", "1", "0"], "why": "The teleport technique."}, {"q": "Two green dots joined by one wire. What do they become?", "a": "one green dot, with the angles added", "w": ["two red dots", "a cup", "a loop with number n"], "why": "The dot-fusion technique."}, {"q": "The yanking rule. Its accepted name?", "a": "the snake equation, or zigzag identity", "w": ["the pentagon identity", "the Bell equation", "the triangle identity"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞ג‎"]=[{"q": "How do chance rules run in a row?", "a": "by multiplying chance grids", "w": ["by adding chances", "by taking the larger chance", "by copying the input"], "why": "Rung 30’s chance grids."}, {"q": "Which chance rules pass through the copying dot?", "a": "only plain functions, one output with chance 1", "w": ["every chance rule", "no rule at all", "only fair coins, chance ½ each"], "why": "The copy-sorts technique."}, {"q": "Which chance rules pass through the ending dot?", "a": "every chance rule", "w": ["only plain functions", "none", "only constant rules"], "why": "Every chance rule ends somewhere."}, {"q": "A joint ψ makes X and Y independent exactly when…", "a": "the picture falls into two pieces, its marginals side by side", "w": ["it passes through the copying dot", "all its chances are equal", "X and Y are the same wire"], "why": "The falls-apart technique."}, {"q": "Turning a rule around, what is g(θ | x)?", "a": "f(x | θ) π(θ) divided by Σ over t of f(x | t) π(t)", "w": ["f(x | θ), the rule unchanged", "π(θ) alone, the prior unchanged", "f(θ | x) π(x)"], "why": "The turn-around technique: Bayes as a bent wire."}, {"q": "Doing t, as against seeing t, cuts which wire?", "a": "the wire into T, from its cause Z", "w": ["the wire out of Y", "every wire", "no wire"], "why": "The cut-the-wire technique."}, {"q": "When do seeing and doing agree?", "a": "when there is no wire from Z to T", "w": ["always", "never", "when Y has two values"], "why": "Cut nothing, change nothing."}, {"q": "A category of chance rules with copy and discard. Its accepted name?", "a": "a Markov category", "w": ["a Kleisli category", "a compact closed category", "a topos"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞ψ"]=[{"q": "Which of the three demands on a measure of surprise asks about a choice made in two stages?", "a": "the grouping demand", "w": ["continuity", "growth with equal outcomes", "symmetry"], "why": "First stage plus the average second."}, {"q": "H(¼, ¼, ½) by grouping equals what?", "a": "H(½, ½) + ½ H(½, ½)", "w": ["2 H(½, ½)", "H(½, ½)", "H(¼, ¼)"], "why": "The grouping technique."}, {"q": "H(X, Y) equals what?", "a": "H(X) + Σ over x of p(x) H(Y | X = x)", "w": ["H(X) · H(Y)", "H(X) − H(Y)", "the larger of H(X), H(Y)"], "why": "The chain-rule technique."}, {"q": "A(mn) = A(m) + A(n) and A grows with n. What is A(n)?", "a": "c log n, for a constant c ≥ 0", "w": ["c n", "n²", "c/n"], "why": "The equal-log technique."}, {"q": "The three demands force which formula?", "a": "c Σ pᵢ log(1/pᵢ)", "w": ["Σ pᵢ²", "max pᵢ", "Σ log pᵢ"], "why": "The forced-formula technique."}, {"q": "The proof runs through which chances, in order?", "a": "equal chances, then fractions, then all chances", "w": ["all chances at once", "fractions only", "two outcomes, then three"], "why": "Adding from multiplying."}, {"q": "The loss of g ∘ f, for maps that keep chances. What is it?", "a": "the loss of f plus the loss of g", "w": ["the larger of the two", "their product", "0"], "why": "The loss-adds technique."}, {"q": "Average surprise. Its accepted name?", "a": "Shannon entropy", "w": ["Kullback–Leibler divergence", "Fisher information", "Tsallis entropy"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞τ"]=[{"q": "A transition of a net fires. What does it do?", "a": "eats some tokens and makes others", "w": ["moves one place", "adds a place", "copies the whole marking"], "why": "A net and its firing rule."}, {"q": "Rung 27’s balanced reaction as a net. What are the places and the tokens?", "a": "the species and the molecules", "w": ["the atoms and the bonds", "the reactions and the rates", "the vessels and the litres"], "why": "One transition per reaction."}, {"q": "y · (out(t) − in(t)) = 0 for every transition t. What follows for y · m?", "a": "it is the same at every marking reached from the start", "w": ["it grows by one each firing", "it is always 0", "it doubles"], "why": "The conserved-weight technique."}, {"q": "A marking whose conserved weight differs from the start’s. Can it be reached?", "a": "no", "w": ["yes, after enough firings", "only once", "only if the net is open"], "why": "The rule-out technique."}, {"q": "Two firings that can both fire and do not need each other’s tokens. What about the order?", "a": "either order reaches the same marking", "w": ["only one order works", "they cannot both fire", "the order doubles the tokens"], "why": "The side-by-side technique: runs are arrows."}, {"q": "Two open nets glued along ports. When is a weight on the glued net conserved?", "a": "exactly when its part on each piece is conserved", "w": ["never", "always", "only on the larger piece"], "why": "The glued-weight technique."}, {"q": "What does a conserved weight do along the rate rule of rung 13?", "a": "stays constant", "w": ["falls to 0", "grows without bound", "swings"], "why": "The rate-keeps-weight technique."}, {"q": "A conserved weight on a net. Its accepted name?", "a": "a P-invariant, or place invariant", "w": ["a T-invariant", "a siphon", "a trap"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞水"]=[{"q": "A lens with a choice in the middle. What goes forward and what comes back?", "a": "a move forward, a payoff back", "w": ["a payoff forward, a move back", "two moves", "nothing back"], "why": "A player as a lens."}, {"q": "When does a plan hold in the context (x, k)?", "a": "when its move earns at least as much under k as every other move", "w": ["when it earns the most of any player", "when every move is tried", "when k is 0"], "why": "The best-reply technique."}, {"q": "Two pieces side by side. When is a pair of moves a rest?", "a": "when each is a best reply with the other’s move held fixed", "w": ["when both players earn the same", "when the first player moves first", "never: side by side has no rest"], "why": "The side-by-side technique."}, {"q": "Two pieces in a row. Who sees what?", "a": "the second player sees the first move", "w": ["the first sees the second move", "neither sees the other", "both see the payoff in advance"], "why": "A game in a row."}, {"q": "In a row, what is fed back to the first player?", "a": "the payoff passed back through the second’s plan", "w": ["nothing", "the first player’s own move", "the second’s move only"], "why": "The in-a-row technique."}, {"q": "Best replies of two pieces chase each other round all four pairs. What follows?", "a": "the whole has no rest in plain moves", "w": ["it has four rests", "it has exactly one rest", "each pair is a rest"], "why": "The no-rest technique."}, {"q": "The newcomer stays out, the firm would fight. Why is it a rest yet suspect?", "a": "the firm would not really fight if the newcomer came in", "w": ["the newcomer gains by staying out", "the firm gains by fighting", "it is not a rest"], "why": "The empty-threat technique."}, {"q": "A rest where no player gains by changing alone. Its accepted name?", "a": "a Nash equilibrium", "w": ["a Pareto optimum", "a dominant strategy", "a minimax value"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞Ξ"]=[{"q": "W ⊆ V ⊆ U and s an answer on U. What is cutting in two steps?", "a": "the same as cutting to W at once", "w": ["the empty answer", "a different answer", "not defined"], "why": "The two-cuts technique."}, {"q": "Answers on pieces that agree on every overlap. What does the gluing rule ask?", "a": "they come from exactly one answer on the whole", "w": ["they agree everywhere already", "they are constant", "they come from two answers"], "why": "The gluing rule."}, {"q": "Do continuous functions glue?", "a": "yes, to exactly one continuous function on the whole", "w": ["no, never", "only when there are two pieces", "only when each piece is constant"], "why": "The continuous-glue technique."}, {"q": "Do bounded functions glue?", "a": "no: agreeing pieces can have no bounded whole", "w": ["yes, always", "only on finite pieces", "only when continuous"], "why": "The bounded-fails technique."}, {"q": "Rung 41’s table of readings on two photons agrees on every overlap. What is missing?", "a": "a joint answer", "w": ["any reading", "an overlap", "a table"], "why": "The no-joint technique."}, {"q": "When can a plan fit the steps round a loop?", "a": "only when the product of the signs round the loop is +1", "w": ["always", "only when every sign is −1", "when the loop has three steps"], "why": "The loop-sign technique."}, {"q": "The limit on a plan of answers in rung 41, said here as what?", "a": "a failure to glue", "w": ["a failure to cut", "a gluing that always works", "a loop with sign +1"], "why": "Local answers that do not glue."}, {"q": "Data on pieces that glues. Its accepted name?", "a": "a sheaf", "w": ["a presheaf", "a bundle", "a cover"], "why": "The cellar."}];
