(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞γ"]=[{"q": "What is kept when the group is forgotten?", "a": "its representations, their maps, side by side, and the forgetful map", "w": ["only the number of its members", "only one representation of it", "the group table, without the group"], "why": "The ways it acts."}, {"q": "For the clock of 3, a choice uₖ with u₀ = 1 and uₖ₊ₗ = uₖ uₗ is what?", "a": "uₖ = zᵏ for a z with z³ = 1", "w": ["uₖ = k", "uₖ = 1 always", "uₖ = 3ᵏ"], "why": "The clock-back technique."}, {"q": "For the shuffles of three, what is W ⊗ W?", "a": "1 + ε + W", "w": ["W", "1 + W", "ε"], "why": "The shuffle-table technique."}, {"q": "And ε ⊗ ε?", "a": "1", "w": ["ε", "W", "0"], "why": "The shuffle-table technique."}, {"q": "Every family of grids that respects everything is ρ(g) for how many g?", "a": "exactly one", "w": ["none", "two", "every g"], "why": "The rebuild technique."}, {"q": "For a turn-about group, rebuilding is which earlier result?", "a": "∞J’s turnings of the turnings", "w": ["the fixed-point technique", "Bayes", "the pentagon rule"], "why": "The double turning."}, {"q": "Why does the forgetful map matter?", "a": "two different groups of eight members have the same table", "w": ["without it no table exists", "it adds members", "it makes the group finite"], "why": "The same-table technique."}, {"q": "Rebuilding a group from its representations. Its accepted name?", "a": "Tannaka–Krein duality", "w": ["Pontryagin duality", "Stone duality", "Galois theory"], "why": "The cellar."}];
