(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞F"]=[{"q": "Atoms of mass m on springs κ, spacing a. The turn rate of a wave of number k?", "a": "2√(κ/m) |sin(ka/2)|", "w": ["√(κ/m) · ka", "κ/m", "2√(κ/m)"], "why": "Atoms on springs."}, {"q": "What is the shortest wave a lattice of spacing a can carry?", "a": "2a", "w": ["a", "a/2", "none: any length"], "why": "The shortest wave."}, {"q": "Long waves on a lattice. How fast do they run?", "a": "at v = a√(κ/m), whatever their length", "w": ["slower the longer they are", "at the speed of light", "not at all"], "why": "The speed of sound."}, {"q": "A lattice wave of turn rate ω at temperature T holds how many steps on average?", "a": "1/(e^(ħω/kT) − 1)", "w": ["kT/ħω exactly", "e^(−ħω/kT)", "½"], "why": "A wave takes energy in steps."}, {"q": "Far below θ, how does a crystal’s heat capacity go with T?", "a": "as T³", "w": ["as T", "as e^(−θ/T)", "it stays at 3Nk"], "why": "The cube law."}, {"q": "Far above θ, what is the heat capacity of N atoms?", "a": "3Nk", "w": ["Nk", "0", "9NkT"], "why": "The 3R rule."}, {"q": "The 3R rule. Its accepted name?", "a": "the law of Dulong and Petit", "w": ["Debye’s law", "the Einstein model", "the Wiedemann–Franz law"], "why": "The cellar."}, {"q": "A step of energy of a lattice wave. Its accepted name?", "a": "a phonon", "w": ["a photon", "a magnon", "a Cooper pair"], "why": "The cellar."}];
