(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞n"]=[{"q": "The prover sends t ≡ gʳ, the checker tosses c, the prover answers s ≡ r + cx. What does the checker test?", "a": "gˢ ≡ t · yᶜ", "w": ["gˢ ≡ t + yᶜ", "gˢ ≡ tᶜ · y", "s ≡ t · yᶜ"], "why": "A commitment, a coin, an answer."}, {"q": "A prover answers both coins, 0 and 1, for one t, with s₀ and s₁. What do the two answers give?", "a": "the secret, x ≡ s₁ − s₀ (mod p − 1)", "w": ["nothing at all", "the commitment r only", "x ≡ s₀ · s₁"], "why": "A cheat ready for one coin."}, {"q": "Twenty rounds with fresh fair coins. A cheat fools the checker with chance at most?", "a": "2⁻²⁰", "w": ["1/20", "½", "20 · 2⁻¹"], "why": "Rounds multiply."}, {"q": "Pick c and s at random, then put t ≡ gˢ y⁻ᶜ. What do these records show?", "a": "the chances of honest rounds: nothing is learned", "w": ["the secret x, one bit at a time", "a cheat, caught every time", "half the bits of the secret x"], "why": "A round written backwards."}, {"q": "What takes the place of the checker’s coin in a signature?", "a": "a fingerprint H(m, t)", "w": ["the signer’s secret x", "the message m alone", "a coin the signer tosses"], "why": "A fingerprint for a coin."}, {"q": "Knowing one of two secrets, the prover writes one round backwards and answers the coin c with c₁ ≡ c − c₂. What does the checker test?", "a": "c₁ + c₂ ≡ c, and both rounds", "w": ["c₁ = c₂", "only the real round", "c₁ · c₂ ≡ c"], "why": "One of two, and not which."}, {"q": "The round with a big coin. Its accepted name?", "a": "the Schnorr identification protocol", "w": ["the Diffie–Hellman exchange", "the RSA signature", "Shamir’s secret sharing"], "why": "The cellar."}, {"q": "Replacing the coin with a fingerprint. Its accepted name?", "a": "the Fiat–Shamir transform", "w": ["the random oracle", "the Chaum–Pedersen proof", "the simulator"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞ח‎"]=[{"q": "Links the same both ways, no self-links, one unit changed at a time. What happens to the loop?", "a": "every change lowers the energy, so it comes to rest", "w": ["it cycles for ever", "the energy rises until it stops", "it rests only when N is even"], "why": "A loop that comes to rest."}, {"q": "Patterns ξ^μ written into links. What is wᵢⱼ?", "a": "(1/N) Σ ξᵢ^μ ξⱼ^μ", "w": ["Σ (ξᵢ^μ + ξⱼ^μ)", "ξᵢ^μ / ξⱼ^μ", "(1/N) Σ ξᵢ^μ"], "why": "Many patterns in one set of links."}, {"q": "p patterns, at right angles in pairs. Every one rests while?", "a": "p < N", "w": ["p < √N", "p < 0.138N", "p < N/2"], "why": "Many patterns in one set of links."}, {"q": "Random patterns of N signs. Near what count does recall break?", "a": "p ≈ 0.138N", "w": ["p ≈ N", "p ≈ √N", "p ≈ N/2"], "why": "How many random patterns fit."}, {"q": "The cue beats every other pattern’s overlap by at least g. The weight on the nearest pattern is at least?", "a": "1/(1 + (p − 1)e^(−βg))", "w": ["e^(−βg)", "1/p", "1 − e^(βg)"], "why": "A soft lookup."}, {"q": "A machine with n knobs is trained on D tokens. About how many multiplications and additions?", "a": "6nD", "w": ["2nD", "nD", "6n²D"], "why": "What a text machine is trained to do."}, {"q": "The loop with links the same both ways. Its accepted name?", "a": "a Hopfield network", "w": ["a perceptron", "a transformer", "a Boltzmann machine"], "why": "The cellar."}, {"q": "The soft lookup inside a text machine. Its accepted name?", "a": "attention", "w": ["convolution", "backpropagation", "dropout"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞九"]=[{"q": "What is a kind’s level in a food web?", "a": "one more than the average level of what it eats", "w": ["one more than the highest level of what it eats", "the number of kinds it eats", "one less than the average level of its eaters"], "why": "A web is a graph with arrows."}, {"q": "Near a rest, x′ ≈ Ax. When does the web hold?", "a": "when every stretch of A has real part below 0", "w": ["when every entry of A is below 0", "when A has no zeros", "when the diagonal sums to 0"], "why": "A pair, read as a grid."}, {"q": "The grid with −d on the diagonal and p, q off it. Its stretches?", "a": "−d ± √(pq)", "w": ["−d ± pq", "d ± √(p + q)", "−p and −q"], "why": "A pair, read as a grid."}, {"q": "A pair whose links p and q have one sign. It holds exactly while?", "a": "pq < d²", "w": ["pq > d²", "p + q < d", "at every strength"], "why": "A pair, read as a grid."}, {"q": "A pair whose links p and q have opposite signs, as eater and eaten. When does it hold?", "a": "at every strength", "w": ["only while pq < d²", "never", "only when p = −q"], "why": "A pair, read as a grid."}, {"q": "In every row, the diagonal entry is below 0 and outweighs the sizes of the others put together. What follows?", "a": "the rest holds, whatever the other signs", "w": ["the rest breaks", "the web has one level", "nothing, without the signs"], "why": "Strong crowding holds any web."}, {"q": "S kinds, linked with chance C, links of spread width σ. A random web holds while?", "a": "σ√(SC) < 1", "w": ["σSC < 1", "σ < √(SC)", "SC < σ"], "why": "A web drawn at random."}, {"q": "The rule σ√(SC) < 1. Its accepted name?", "a": "May’s stability criterion", "w": ["the Allesina–Tang criterion", "Gershgorin’s circle theorem", "the Lotka–Volterra rule"], "why": "The cellar."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["∞B"]=[{"q": "A machine in log room, on an input of length n. When does it stop?", "a": "within a power of n steps, or never", "w": ["within log n steps", "within 2ⁿ steps, always", "only on short inputs"], "why": "Room smaller than the input."}, {"q": "How does more room decide more?", "a": "by the diagonal, with a counter to catch loops", "w": ["by guessing", "by counting dots layer by layer", "by a list of not-and gates"], "why": "More room decides more."}, {"q": "Without guessing, a path from u to v in a graph of N dots is found in room about?", "a": "(log₂ N)²", "w": ["log₂ N", "N", "√N"], "why": "A path in squared room."}, {"q": "With guessing, the same path question needs room about?", "a": "log₂ N", "w": ["(log₂ N)²", "N", "1"], "why": "A path in squared room."}, {"q": "How does a guessing machine in log room certify that v is not reached?", "a": "it counts the dots reached, layer by layer", "w": ["it tries every path at once", "it guesses a path and fails", "it cannot certify a no"], "why": "A count certifies a no."}, {"q": "Evaluating a list of not-and gates. Which is true?", "a": "it is fast, and every fast set reduces to it in log room", "w": ["it needs a power of 2 steps", "it is decided in log room", "it is not fast"], "why": "Log room against fast."}, {"q": "Log room equals fast exactly when?", "a": "gate lists can be run in log room", "w": ["guessing adds nothing to room", "paths need squared room", "every set is fast"], "why": "Log room against fast."}, {"q": "The result that guessing log room can certify a no. Its accepted name?", "a": "the Immerman–Szelepcsényi theorem", "w": ["Savitch’s theorem", "Reingold’s theorem", "the space hierarchy theorem"], "why": "The cellar."}];
